WITH deduped AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY status, customer_id ORDER BY monthly_fee, id) AS row_num FROM subscriptions QUALIFY row_num = 1) SELECT status, AVG(monthly_fee) AS avg_monthly_fee, APPROX_PERCENTILE(monthly_fee, 0.5) AS monthly_fee_p50, SUM(monthly_fee) FILTER (WHERE status = 'EXPIRED') AS expired_total_monthly_fee, SUM(monthly_fee) AS total_monthly_fee FROM deduped GROUP BY status HAVING expired_total_monthly_fee > 0 ORDER BY avg_monthly_fee NULLS LAST;
